    "bespoke": [
      "function refFilter(v){v=(v||'').toLowerCase().trim();document.querySelectorAll('.bw-panel.active .ref-table tr').forEach(tr=>{if(tr.querySelector('th'))return;tr.classList.toggle('hide',v&&!tr.textContent.toLowerCase().includes(v));});}",
      "function calcCyl(){const D=+cf_d.value/1000,d=+cf_r.value/1000,P=+cf_p.value*1e5,Q=+cf_q.value/60000;const A=Math.PI*D*D/4,Ar=A-Math.PI*d*d/4;let o=`Extend: ${f2(A*P/1000)} kN (${f2(A*P/9.81)} kgf, ${f2(A*P*0.2248)} lbf)<br>Retract: ${f2(Ar*P/1000)} kN (${f2(Ar*P/9.81)} kgf)<br>Area ratio: ${f2(A/Ar)}:1`;if(Q>0)o+=`<br>Extend speed: ${f2(Q/A*1000)} mm/s &nbsp; Retract: ${f2(Q/Ar*1000)} mm/s`;cf_out.innerHTML=o;}",
      "function calcTP(){const kw=+tp_kw.value,n=+tp_n.value,i=+tp_i.value||1,e=(+tp_e.value||100)/100;const T=9550*kw/n;tp_out.innerHTML=`Input torque: ${f2(T)} Nm (${f2(T*0.7376)} ft·lb) at ${n} rpm<br>Output: ${f2(T*i*e)} Nm (${f2(T*i*e*0.7376)} ft·lb) at ${f2(n/i)} rpm<br>${kw} kW = ${f2(kw*1.341)} HP`;}",
      "function calcBelt(){const d1=+bd_d1.value,d2=+bd_d2.value,n=+bd_n.value,c=+bd_c.value;const n2=n*d1/d2,v=Math.PI*d1/1000*n;const L=2*c+1.57*(d1+d2)+Math.pow(d2-d1,2)/(4*c);const span=Math.sqrt(c*c-Math.pow((d2-d1)/2,2));bd_out.innerHTML=`Driven speed: ${f2(n2)} rpm (ratio ${f2(d2/d1)}:1)<br>Belt speed: ${f2(v)} m/min (${f2(v*3.281)} ft/min)<br>Belt pitch length: ${f2(L)} mm (${f2(L/25.4)} in)<br>Span: ${f2(span)} mm → deflection target ${f2(span/64)} mm`;}",
      "function calcChain(){const p=+ce_no.value/8*25.4,n=+ce_n.value,l=+ce_l.value,lim=ce_big.value==='1'?1.5:3;const nom=p*n,el=(l-nom)/nom*100;let st=el<lim*0.5?'well within limit':el<lim?'wearing: plan the replacement':'PAST LIMIT: replace now, inspect sprockets';ce_out.innerHTML=`Pitch: ${f2(p)} mm &nbsp; Nominal over ${n} pitches: ${f2(nom)} mm<br>Elongation: ${f2(el)}% against a ${lim}% limit<br>${st}`;}",
      "function calcAlign(){const rim=+al_rim.value,face=+al_face.value,dia=+al_dia.value,fi=+al_in.value,fo=+al_outf.value,rpm=+al_rpm.value;const off=rim/2,ang=face/dia;const tol=rpm<=1000?[0.13,0.10]:rpm<=2000?[0.10,0.08]:rpm<=3000?[0.07,0.07]:rpm<=4000?[0.05,0.06]:[0.04,0.05];al_out.innerHTML=`Offset at coupling: ${f2(off)} mm (acceptable ${tol[0]} mm at ${rpm} rpm)<br>Angularity: ${(ang*100).toFixed(3)} mm/100 mm (acceptable ${tol[1]})<br>Inboard foot correction: ${f2(off+ang*fi)} mm<br>Outboard foot correction: ${f2(off+ang*fo)} mm<br>Direction depends on your sign convention: write it down before you start.`;}",
      "function calcGrease(){const d=+gq_d.value,b=+gq_b.value,s=+gq_s.value||1;const g=0.005*d*b;gq_out.innerHTML=`Quantity: ${f2(g)} g<br>About ${Math.round(g/s)} strokes of your gun (${s} g per stroke)<br>Relief plug out. Slowly. Let it purge.`;}",
      "function calcBF(){const n=+bf_n.value,f=+bf_rpm.value/60;bf_out.innerHTML=`Shaft: ${f2(f)} Hz (1x)<br>BPFO ≈ ${f2(0.4*n*f)} Hz (${f2(0.4*n)}x) &nbsp; BPFI ≈ ${f2(0.6*n*f)} Hz (${f2(0.6*n)}x)<br>FTF ≈ ${f2(0.4*f)} Hz (0.4x) &nbsp; BPFO + BPFI = ${n}x<br>Rule of thumb only; use the bearing number for exact values.`;}",
      "function ucSetup(){const t=uc_type.value,u=Object.keys(UC[t]);uc_from.innerHTML=u.map(x=>`<option>${x}</option>`).join('');uc_to.innerHTML=u.map(x=>`<option>${x}</option>`).join('');uc_to.selectedIndex=Math.min(1,u.length-1);ucCalc();}",
      "function ucCalc(){const t=uc_type.value,v=+uc_val.value;if(t==='Temperature'){const a=uc_from.value,b=uc_to.value;let c=a==='°C'?v:(v-32)/1.8;let r=b==='°C'?c:c*1.8+32;uc_out.innerHTML=`${v} ${a} = ${f2(r)} ${b}`;return;}const r=v*UC[t][uc_from.value]/UC[t][uc_to.value];uc_out.innerHTML=`${v} ${uc_from.value} = ${r.toLocaleString(undefined,{maximumFractionDigits:4})} ${uc_to.value}`;}"
    ],
